18: /**
19:  * 权限配置读取器与管理器。
20:  * <p>
21:  * 负责维护当前权限模式（{@link PermissionMode}），
22:  * 并从用户本地配置路径（{@code ~/.butvan-agent/permissions.yaml}）装载自定义权限规则列表，
23:  * 供 {@link AgentSecurity} 转化为 AgentScope 原生 {@link io.agentscope.core.permission.PermissionContextState}。
24:  */
25: @Slf4j
26: public class PermissionChecker {
27: 
28:     /** 当前系统的运行权限模式 */
29:     @Getter
30:     private PermissionMode mode;
31: 
32:     /** 当前项目根路径 */
33:     private final Path projectRoot;
34: 
35:     /** 从 YAML 解析装载的 AgentScope 原生权限规则列表 */
36:     @Getter
37:     private final List<PermissionRule> fileRules;
38: 
39:     /**
40:      * 构造权限配置检查器。
41:      *
42:      * @param mode        初始运行权限模式（若为 null 则默认为 AgentScope DEFAULT 模式）
43:      * @param projectRoot 当前项目根路径
44:      */
45:     public PermissionChecker(PermissionMode mode, Path projectRoot) {
46:         this.mode = mode != null ? mode : PermissionMode.DEFAULT;
47:         this.projectRoot = projectRoot != null
48:                 ? projectRoot.toAbsolutePath().normalize()
49:                 : Paths.get(".").toAbsolutePath().normalize();
50:         this.fileRules = new ArrayList<>(loadRules());
51:     }
52: 
53:     /**
54:      * 动态更新运行权限模式。
55:      *
56:      * @param mode 新的权限模式
57:      */
58:     public void setMode(PermissionMode mode) {
59:         this.mode = mode != null ? mode : PermissionMode.DEFAULT;
60:     }
61: 
62:     /**
63:      * 从本地用户配置路径装载三层 YAML 权限规则。
64:      *
65:      * @return 解析完成的 PermissionRule 规则列表
66:      */
67:     private List<PermissionRule> loadRules() {
68:         List<PermissionRule> rules = new ArrayList<>();
69: 
70:         // 默认用户配置文件路径: ~/.butvan-agent/permissions.yaml
71:         Path userConfigPath = Paths.get(System.getProperty("user.home"), ".butvan-agent", "permissions.yaml");
72: 
73:         if (Files.exists(userConfigPath)) {
74:             log.info("[PermissionChecker] 检测到本地权限配置文件: {}", userConfigPath);
75:             rules.addAll(parseYamlRules(userConfigPath));
76:         } else {
77:             log.debug("[PermissionChecker] 未检测到本地权限配置文件，将使用默认内置规则。");
78:         }
79: 
80:         return rules;
81:     }
82: 
83:     /**
84:      * 解析 YAML 文件并转换为 AgentScope 原生 PermissionRule。
85:      *
86:      * @param yamlPath YAML 文件绝对路径
87:      * @return 解析出的 PermissionRule 列表
88:      */
89:     @SuppressWarnings("unchecked")
90:     private List<PermissionRule> parseYamlRules(Path yamlPath) {
91:         List<PermissionRule> rules = new ArrayList<>();
92:         try (InputStream in = Files.newInputStream(yamlPath)) {
93:             Yaml yaml = new Yaml();
94:             Map<String, Object> data = yaml.load(in);
95: 
96:             if (data != null && data.containsKey("rules")) {
97:                 List<Map<String, Object>> ruleList = (List<Map<String, Object>>) data.get("rules");
98:                 for (Map<String, Object> map : ruleList) {
99:                     String toolName = (String) map.getOrDefault("tool", "*");
100:                     String pattern = (String) map.getOrDefault("pattern", ".*");
101:                     String action = (String) map.getOrDefault("action", "ALLOW");
102: 
103:                     PermissionBehavior behavior = switch (action.toUpperCase()) {
104:                         case "DENY" -> PermissionBehavior.DENY;
105:                         case "ASK" -> PermissionBehavior.ASK;
106:                         default -> PermissionBehavior.ALLOW;
107:                     };
108: 
109:                     // 直接构造 AgentScope 原生 PermissionRule
110:                     rules.add(new PermissionRule(toolName, pattern, behavior, "Layer2-YamlUserRule"));
111:                 }
112:             }
113:         } catch (Exception e) {
114:             log.error("[PermissionChecker] 解析 YAML 权限文件失败: {}", yamlPath, e);
115:         }
116:         return rules;
117:     }
118: }

